WITH remaining_keys AS (SELECT id, country FROM suppliers EXCEPT ALL SELECT id, country FROM suppliers WHERE rating IS NULL), kept_rows AS (SELECT s.* FROM suppliers s JOIN remaining_keys k ON s.id = k.id AND s.country = k.country) SELECT city, rating, CASE WHEN city RLIKE '^(London|Berlin)$' THEN 'GROUP_A' ELSE 'EXTENDED' END AS city_zone FROM kept_rows ORDER BY city_zone DESC NULLS LAST
